  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$Seuls les 1 000 € situés dans la tranche à 41 % économisent ce taux ; les 4 000 € suivants retombent dans la tranche à 30 %. Appliquer la TMI à tout le versement surestime l'économie de plusieurs centaines d'euros, erreur signalée dans la leçon 2.$academy_seed$);
