  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$L'AMF rappelle que le gain d'un Girardin réside uniquement dans la réduction d'impôt, que l'apport ne revient pas et que la réduction peut être reprise même sans faute de l'investisseur. L'agrément ne supprime pas ce risque. Nommer les contraintes aussi clairement que l'avantage est la règle de la leçon 3.$academy_seed$);
