  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 2, $academy_seed$Les cinq questions de la leçon 3 placent la liquidité et l'épargne de précaution avant l'avantage fiscal. Un projet locatif à un an et l'absence de réserve rendent tout blocage inadapté, quel que soit le montant. Le conseil suit la méthode du cabinet : écoute et étude avant proposition.$academy_seed$);
